style.css:
@-moz-document domain("google.com") {
/* 1. ФИРМЕННЫЙ ШРИФТ XIAOMI (MI SANS) */
    /* Здесь мы указываем ваш скачанный шрифт */
    body, textarea, input, select {
        font-family: 'Mi Sans', sans-serif !important; 
    }

    /* 2. ОРАНЖЕВЫЙ ЛОГОТИП GOOGLE (имитация акцента Xiaomi) */
    .lnXdpd {
        /* Этот фильтр перекрашивает логотип в оранжевый */
        filter: hue-rotate(240deg) saturate(200%) brightness(100%) sepia(80%) hue-rotate(-120deg) saturate(400%) !important;
        /* Код кажется сложным, но он эффективно меняет цвета Google на оранжевые */
    }

    /* 3. ГРАФИКА XIAOMI (Скругление и фирменные тени) */
    .RNNXgb {
        border-radius: 20px !important; /* Умеренное скругление, как в MIUI */
        box-shadow: 0 4px 12px rgba(255, 103, 0, 0.25) !important; /* Насыщенная, оранжевая тень */
        border: none !important;
    }

    /* 4. ОРАНЖЕВЫЕ КНОПКИ (Акцентный цвет) */
    .gNO89b, .Tg7LZd, .z1asce {
        background-color: #ff6700 !important; /* Насыщенный оранжевый Xiaomi */
        border: none !important;
        color: white !important;
        border-radius: 12px !important; /* Скругление кнопок */
        font-weight: bold !important;
    }

    /* 5. ПОИСКОВАЯ СТРОКА (Текст) */
    .gLFyf {
        font-size: 16px !important;
    }
}
